#!/bin/bash
set -euo pipefail
echo "Pasta atual: $(pwd)"
test -f package.json && test -d src/routes || { echo "ERRO: entra na pasta giro-certo-api primeiro"; exit 1; }
git checkout main
git pull origin main
mkdir -p src/services
python3 - <<"PY"
import base64, pathlib
pathlib.Path("src/services/bike-maintenance-bootstrap.service.ts").write_bytes(base64.b64decode(""))
pathlib.Path("src/routes/bikes.routes.ts").write_bytes(base64.b64decode(""))
print("OK: ficheiros criados/atualizados")
PY
test -f src/services/bike-maintenance-bootstrap.service.ts
grep -q resolveBikeForMaintenance src/routes/bikes.routes.ts
git add src/services/bike-maintenance-bootstrap.service.ts src/routes/bikes.routes.ts
git status
git commit -m "fix(maintenance): moto fallback + baseline de km sem novo build"
git push origin main
echo "SUCESSO: push feito. Espera o Render ficar Live."
